            best_pos = -1
            best_delta = None
            dc = demands[c]
            r = 0
            while r < len(routes):
                if route_load(routes[r]) + dc <= capacity:
                    route = routes[r]
                    pos = 0
                    while pos <= len(route):
                        prev_node = depot if pos == 0 else route[pos - 1]
                        next_node = depot if pos == len(route) else route[pos]
                        delta = dist(prev_node, c) + dist(c, next_node) - dist(prev_node, next_node)
                        if best_delta is None or delta < best_delta - 1e-12 or (delta == best_delta and (r < best_r or (r == best_r and pos < best_pos))):
                            best_delta = delta
                            best_r = r
                            best_pos = pos
                        pos += 1
                r += 1
            if best_r >= 0:
                routes[best_r].insert(best_pos, c)
            else:
                routes.append([c])

    # Remove duplicates by keeping first occurrence and repairing any omissions
    seen = {}
    cleaned = []
    for route in routes:
        new_route = []
        load = 0
        for c in route:
            if c == depot or seen.get(c, 0):
                continue
            if load + demands[c] <= capacity:
                new_route.append(c)
                load += demands[c]
                seen[c] = 1
        if new_route:
            cleaned.append(new_route)
    routes = cleaned

    for c in customers:
        if not seen.get(c, 0):
            placed = False
            best_r = -1
            best_pos = -1
            best_delta = None
            dc = demands[c]
            r = 0
            while r < len(routes):
                if route_load(routes[r]) + dc <= capacity:
                    route = routes[r]
                    pos = 0
                    while pos <= len(route):
                        prev_node = depot if pos == 0 else route[pos - 1]
                        next_node = depot if pos == len(route) else route[pos]
                        delta = dist(prev_node, c) + dist(c, next_node) - dist(prev_node, next_node)
                        if best_delta is None or delta < best_delta - 1e-12:
                            best_delta = delta
                            best_r = r
                            best_pos = pos
                        pos += 1
                r += 1
            if best_r >= 0:
                routes[best_r].insert(best_pos, c)
            else:
                routes.append([c])

    # Final deterministic route polishing
    r = 0
    while r < len(routes):
        route = routes[r]
        if len(route) >= 3:
            improved = True
            while improved:
                improved = False
                n = len(route)
                i = 0
                while i < n - 2 and not improved:
                    j = i + 2
                    while j < n:
                        old = route_cost(route)
                        cand = route[:i + 1] + route[i + 1:j + 1][::-1] + route[j + 1:]
                        if route_cost(cand) + 1e-12 < old:
                            route = cand
                            routes[r] = route
                            improved = True
                            break
                        j += 1
                    i += 1
        r += 1

    return routes
